function ParticipantWorkspace() {
  const [saved, setSaved] = useState(false);
  const [sync, setSync] = useState<"Offline" | "Pending sync" | "Synced">("Synced");
  const [validation, setValidation] = useState(false);
  const participant = participants[0];
  const validate = () => { setValidation(true); setSaved(false); };
  const submit = () => { setSaved(true); setSync("Pending sync"); setTimeout(() => setSync("Synced"), 1200); };
  return <div className="page-content"><div className="breadcrumb"><Link href="/participants">Participants</Link><span>/</span><span>{participant.id}</span></div><div className="page-heading"><div><div className="eyebrow">Participant profile · {participant.id}</div><h1>Participant {participant.id}</h1><p className="page-subtitle">{participant.study} · {participant.site} · Enrolled 02 Apr 2026</p></div><div className="heading-actions"><Badge tone="green">{participant.status}</Badge><button className="button button-outline"><Network size={16} /> QR workflow</button></div></div><section className="participant-overview"><div className="participant-card panel"><div className="participant-avatar">AS</div><div><span className="eyebrow">Current visit</span><h2>Week 4 · Treatment review</h2><p>Next visit: 30 Apr 2026 · Window ± 3 days</p></div><div className="participant-meta"><div><span>Treatment group</span><strong>{participant.treatment}</strong></div><div><span>Prakriti</span><strong>Vata–Pitta</strong></div><div><span>Consent</span><strong className="inline-success"><CheckCircle2 size={15} /> Current</strong></div></div></div><div className="timeline panel"><div className="panel-header"><div><div className="eyebrow">Participant journey</div><h2>Visit timeline</h2></div><Badge tone="blue">4 of 7 visits</Badge></div><div className="timeline-track">{["Screening", "Baseline", "Week 4", "Week 8", "Follow-up"].map((step, index) => <div className={`timeline-step ${index < 2 ? "done" : index === 2 ? "current" : ""}`} key={step}><div className="timeline-dot">{index < 2 ? <Check size={13} /> : index === 2 ? <span /> : null}</div><span>{step}</span>{index === 2 && <small>Today</small>}</div>)}</div></div></section><section className="dashboard-grid workflow-grid"><div className="panel form-panel"><div className="panel-header"><div><div className="eyebrow">Clinical data entry</div><h2>Week 4 treatment review</h2></div><div className={`sync-pill sync-${sync.toLowerCase().replace(" ", "-")}`}><span />{sync}</div></div><div className="form-notice"><ClipboardCheck size={17} /><div><strong>Required fields marked with *</strong><p>Data is validated before submission and recorded in the audit trail.</p></div></div><div className="field-grid"><label>Visit date *<input defaultValue="2026-04-28" type="date" /></label><label>Body weight (kg) *<input defaultValue="68.4" type="number" /></label><label>HbA1c (%) *<input defaultValue="7.2" type="number" step="0.1" /></label><label>Blood pressure *<input defaultValue="128/82" /></label><label>Ayurvedic assessment<span className="field-help">Prakriti response</span><select defaultValue="Improving"><option>Improving</option><option>Stable</option><option>Worsening</option></select></label><label>Adherence (%) *<input defaultValue="92" type="number" /></label><label className="full-field">Investigator notes<textarea defaultValue="Participant reports improved sleep and consistent adherence. No new adverse symptoms reported." /></label></div>{validation && <div className="validation-success"><CheckCircle2 size={18} /><div><strong>Validation passed</strong><p>All required fields complete. Range and visit-date checks passed. Ready to submit.</p></div></div>}{saved && <div className="submit-success"><CheckCircle2 size={18} /><div><strong>Visit record submitted</strong><p>Analytics updated, audit trail recorded and the site coordinator was notified.</p></div></div>}<div className="form-actions"><span className="form-source"><FileText size={14} /> Source: Week 4 CRF v1.1</span><div><button className="button button-outline" onClick={() => { setSync("Pending sync"); setTimeout(() => setSync("Synced"), 800); }}>Save draft</button><button className="button button-outline" onClick={validate}>Validate data</button><button className="button button-primary" disabled={!validation} onClick={submit}>Submit record <ArrowRight size={16} /></button></div></div></div><div className="panel side-panel"><div className="panel-header"><div><div className="eyebrow">Data quality</div><h2>Record checks</h2></div><Badge tone={validation ? "green" : "amber"}>{validation ? "Passed" : "Review"}</Badge></div><div className="check-list"><div><span className="check-state done"><Check size={13} /></span><div><strong>Required fields</strong><small>All 6 required fields present</small></div></div><div><span className="check-state done"><Check size={13} /></span><div><strong>Value ranges</strong><small>Within protocol-defined ranges</small></div></div><div><span className="check-state pending">!</span><div><strong>Visit date sequence</strong><small>Validate before submitting</small></div></div><div><span className="check-state neutral">—</span><div><strong>Duplicate record</strong><small>Checked on submission</small></div></div></div><div className="audit-note"><ShieldCheck size={16} /><span>Every submission is immutable in the audit trail.</span></div></div></section></div>;
}

function CopilotWorkspace() {
  const [question, setQuestion] = useState("");
  const [authNotice, setAuthNotice] = useState(false);
  const auth = trpc.auth.me.useQuery();
  const context = trpc.research.context.useQuery(undefined, { enabled: Boolean(auth.data), retry: false });
  const ask = trpc.research.ask.useMutation();
  const suggested = ["Which visits are overdue?", "Which sites have low recruitment?", "Which approvals expire this month?", "Which studies have data-quality issues?", "Which SAE cases require review?", "What are the current study risks?"];
  const submit = (value = question) => {
    const trimmed = value.trim();
    if (!trimmed) return;
    if (!auth.data) {
      setAuthNotice(true);
      return;
    }
    setQuestion(trimmed);
    ask.mutate({ question: trimmed, studyId: context.data?.authorizedStudyIds[0] });
  };
  return <div className="page-content"><ModuleHeader title="AI Research Copilot" eyebrow="Evidence-aware assistant" icon={MessageSquareText} description="Ask practical questions about authorized study data. Every answer shows sources, limitations and a human-review boundary." action="View scope" /><div className="adapter-strip"><ShieldCheck size={16} /><div><strong>Authorized research scope</strong><span>{context.data ? `${context.data.userRole} · ${context.data.authorizedStudyIds.join(", ")}` : "Secure institutional session required before data is loaded"}</span></div><Badge tone={context.data ? "green" : "blue"}>{context.data?.developmentData ? "Development data" : "Permission aware"}</Badge></div><section className="panel copilot-panel"><div className="copilot-header"><div className="copilot-mark"><MessageSquareText size={22} /></div><div><h2>Research Copilot</h2><p>Structured application data only. No live CTRI, hospital/FHIR or external LLM source is used.</p></div><Badge tone="amber">Human review required</Badge></div><div className="copilot-scope"><span>It can help with</span><b>Studies</b><b>Participants</b><b>Visits</b><b>Clinical data</b><b>Safety</b><b>Compliance</b></div><div className="prompt-grid">{suggested.map(prompt => <button className="prompt-chip" key={prompt} onClick={() => submit(prompt)}>{prompt}<ArrowRight size={14} /></button>)}</div>{(authNotice || ask.error) && <div className="permission-state copilot-error"><ShieldCheck size={18} /><div><strong>Secure session required</strong><p>Your institutional session could not be verified. No unscoped records were returned.</p></div></div>}{ask.data && <div className="copilot-answer"><div className="eyebrow">Answer · {ask.data.developmentData ? "development data" : "authorized data"}</div><h3>{ask.data.answer}</h3><div className="source-row"><span>Source records</span>{ask.data.sources.map(source => <Badge tone="blue" key={source.id}>{source.id} · {source.entity}</Badge>)}</div><div className="limitation-row"><AlertCircle size={14} /><span>{ask.data.limitations.join(" ")}</span></div></div>}<div className="copilot-input"><input value={question} onChange={event => setQuestion(event.target.value)} onKeyDown={event => { if (event.key === "Enter") submit(); }} placeholder="Ask about your authorized research data..." aria-label="Research Copilot question" /><button className="button button-primary" onClick={() => submit()} disabled={ask.isPending}>{ask.isPending ? "Reviewing…" : "Ask"} <ArrowRight size={16} /></button></div></section></div>;
}

function ModuleHeader({ title, eyebrow, icon: Icon, description, action = "New record" }: { title: string; eyebrow: string; icon: React.ComponentType<{ size?: number }>; description: string; action?: string }) {
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="page-subtitle">{description}</p></div><button className="button button-primary"><Icon size={16} /> {action}</button></div>;
}

